.macro CHK2 insn, op1, op2, exp
    li   t0, \op1
    li   t1, \op2
    \insn t2, t0, t1
    li   t3, \exp
    beq  t2, t3, 1f
    addi s0, s0, 1
1:
.endm

.macro CHK2W enc, op1, op2, exp
    li   t0, \op1
    li   t1, \op2
    .word \enc
    li   t3, \exp
    beq  t2, t3, 1f
    addi s0, s0, 1
1:
.endm

.macro CHK1 insn, op1, exp
    li   t0, \op1
    \insn t2, t0
    li   t3, \exp
    beq  t2, t3, 1f
    addi s0, s0, 1
1:
.endm

.macro CHK1W enc, op1, exp
    li   t0, \op1
    .word \enc
    li   t3, \exp
    beq  t2, t3, 1f
    addi s0, s0, 1
1:
.endm

.macro CHK1I insn, op1, imm, exp
    li   t0, \op1
    \insn t2, t0, \imm
    li   t3, \exp
    beq  t2, t3, 1f
    addi s0, s0, 1
